CREATE TABLE IF NOT EXISTS public.nv_settings(empresa_id uuid PRIMARY KEY REFERENCES public.empresas(id),data jsonb NOT NULL DEFAULT '{}',revision integer NOT NULL DEFAULT 0,updated_by text NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.nv_grants(id uuid PRIMARY KEY,empresa_id uuid NOT NULL REFERENCES public.empresas(id),actor text NOT NULL,permission text NOT NULL,reason text NOT NULL,granted_by text NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS nv_grant_lookup ON public.nv_grants(empresa_id,actor,permission,expires_at);
CREATE TABLE IF NOT EXISTS public.nv_professionals(empresa_id uuid NOT NULL REFERENCES public.empresas(id),funcionario_id uuid NOT NULL REFERENCES public.funcionarios(id),data jsonb NOT NULL,revision integer NOT NULL DEFAULT 1,updated_by text NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(empresa_id,funcionario_id));
CREATE TABLE IF NOT EXISTS public.nv_audit(id bigserial PRIMARY KEY,empresa_id uuid NOT NULL REFERENCES public.empresas(id),actor text NOT NULL,action text NOT NULL,reference text NOT NULL,details jsonb NOT NULL DEFAULT '{}',at timestamptz NOT NULL DEFAULT now(),previous_hash text NOT NULL,hash text NOT NULL);
CREATE INDEX IF NOT EXISTS nv_audit_lookup ON public.nv_audit(empresa_id,id);
CREATE TABLE IF NOT EXISTS public.nv_lab_catalog(id uuid PRIMARY KEY,empresa_id uuid NOT NULL REFERENCES public.empresas(id),code text NOT NULL,version integer NOT NULL CHECK(version>0),data jsonb NOT NULL,created_by text NOT NULL,approved_by text,approved_at timestamptz,retired_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(empresa_id,id),UNIQUE(empresa_id,code,version));
CREATE TABLE IF NOT EXISTS public.nv_lab_orders(id uuid PRIMARY KEY,empresa_id uuid NOT NULL REFERENCES public.empresas(id),patient_id integer NOT NULL,episode_id uuid,accession text NOT NULL UNIQUE,patient_snapshot jsonb NOT NULL,request_hash text NOT NULL,priority text NOT NULL CHECK(priority IN ('rotina','urgente','emergente')),indication text NOT NULL,origin text NOT NULL,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),cancelled_at timestamptz,cancel_reason text,request_id uuid NOT NULL,UNIQUE(empresa_id,id),UNIQUE(empresa_id,created_by,request_id),FOREIGN KEY(empresa_id,patient_id) REFERENCES public.pacientes(empresa_id,id));
CREATE TABLE IF NOT EXISTS public.nv_lab_tests(id uuid PRIMARY KEY,empresa_id uuid NOT NULL,order_id uuid NOT NULL,catalog_id uuid NOT NULL,snapshot jsonb NOT NULL,result_id integer,UNIQUE(empresa_id,id),FOREIGN KEY(empresa_id,order_id) REFERENCES public.nv_lab_orders(empresa_id,id),FOREIGN KEY(empresa_id,catalog_id) REFERENCES public.nv_lab_catalog(empresa_id,id),FOREIGN KEY(empresa_id,result_id) REFERENCES public.resultados(empresa_id,id));
CREATE TABLE IF NOT EXISTS public.nv_lab_containers(id uuid PRIMARY KEY,empresa_id uuid NOT NULL,order_id uuid NOT NULL,sample_id uuid NOT NULL,parent_id uuid,code text NOT NULL UNIQUE,material text NOT NULL,container text NOT NULL,location text NOT NULL,status text NOT NULL DEFAULT 'por_colher',revision integer NOT NULL DEFAULT 1,collected_at timestamptz,collected_by text,received_at timestamptz,print_count integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(empresa_id,id),FOREIGN KEY(empresa_id,order_id) REFERENCES public.nv_lab_orders(empresa_id,id),FOREIGN KEY(empresa_id,parent_id) REFERENCES public.nv_lab_containers(empresa_id,id));
CREATE TABLE IF NOT EXISTS public.nv_lab_container_tests(empresa_id uuid NOT NULL,container_id uuid NOT NULL,test_id uuid NOT NULL,PRIMARY KEY(empresa_id,container_id,test_id),FOREIGN KEY(empresa_id,container_id) REFERENCES public.nv_lab_containers(empresa_id,id),FOREIGN KEY(empresa_id,test_id) REFERENCES public.nv_lab_tests(empresa_id,id));
CREATE TABLE IF NOT EXISTS public.nv_lab_events(id uuid PRIMARY KEY,empresa_id uuid NOT NULL,container_id uuid NOT NULL,actor text NOT NULL,action text NOT NULL,details jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),request_id uuid NOT NULL,UNIQUE(empresa_id,request_id),FOREIGN KEY(empresa_id,container_id) REFERENCES public.nv_lab_containers(empresa_id,id));
CREATE TABLE IF NOT EXISTS public.nv_lab_values(id uuid PRIMARY KEY,empresa_id uuid NOT NULL,test_id uuid NOT NULL,container_id uuid NOT NULL,version integer NOT NULL CHECK(version>0),data jsonb NOT NULL,reason text NOT NULL DEFAULT '',entered_by text NOT NULL,technical_by text,technical_at timestamptz,released_by text,released_at timestamptz,critical boolean NOT NULL DEFAULT false,request_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(empresa_id,id),UNIQUE(empresa_id,test_id,version),UNIQUE(empresa_id,request_id),FOREIGN KEY(empresa_id,test_id) REFERENCES public.nv_lab_tests(empresa_id,id),FOREIGN KEY(empresa_id,container_id) REFERENCES public.nv_lab_containers(empresa_id,id));
CREATE TABLE IF NOT EXISTS public.nv_lab_communications(id uuid PRIMARY KEY,empresa_id uuid NOT NULL,value_id uuid NOT NULL,actor text NOT NULL,recipient text NOT NULL,channel text NOT NULL,note text NOT NULL,acknowledged boolean NOT NULL,readback text NOT NULL,request_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(empresa_id,request_id),FOREIGN KEY(empresa_id,value_id) REFERENCES public.nv_lab_values(empresa_id,id));
CREATE TABLE IF NOT EXISTS public.nv_quality(id uuid PRIMARY KEY,empresa_id uuid NOT NULL REFERENCES public.empresas(id),sector text NOT NULL,equipment text NOT NULL,reagent_lot text NOT NULL,outcome text NOT NULL CHECK(outcome IN ('aprovado','reprovado','bloqueado')),note text NOT NULL,valid_until timestamptz NOT NULL,actor text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS nv_quality_lookup ON public.nv_quality(empresa_id,sector,created_at);
CREATE TABLE IF NOT EXISTS public.nv_cases(id uuid PRIMARY KEY,empresa_id uuid NOT NULL REFERENCES public.empresas(id),kind text NOT NULL,patient_id integer,episode_id uuid,reference text NOT NULL,title text NOT NULL,status text NOT NULL DEFAULT 'aberto',data jsonb NOT NULL,revision integer NOT NULL DEFAULT 1,created_by text NOT NULL,assigned_to text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(empresa_id,id),FOREIGN KEY(empresa_id,patient_id) REFERENCES public.pacientes(empresa_id,id));
CREATE TABLE IF NOT EXISTS public.nv_case_events(id uuid PRIMARY KEY,empresa_id uuid NOT NULL,case_id uuid NOT NULL,actor text NOT NULL,action text NOT NULL,note text NOT NULL,snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(empresa_id,case_id) REFERENCES public.nv_cases(empresa_id,id));
CREATE TABLE IF NOT EXISTS public.nv_chat_attachments(id uuid PRIMARY KEY,empresa_id uuid NOT NULL, message_id uuid NOT NULL REFERENCES public.hospital_messages(id),name text NOT NULL,mime text NOT NULL,content bytea NOT NULL,size_bytes integer NOT NULL CHECK(size_bytes BETWEEN 1 AND 5242880),sha256 text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
